export const normalizeAdminLocale = (locale) => locale === "en" ? "en" : "vi";
export function adminTranslate(locale, key, params = {}) {
  const text = adminMessages[normalizeAdminLocale(locale)][key] ?? adminMessages.vi[key];
  if (text === undefined) throw new Error(`Missing Admin translation: ${key}`);
  return text.replace(/\{([a-zA-Z]+)\}/g, (match, name) => Object.hasOwn(params, name) ? String(params[name]) : match);
}

export function readAdminLocale(storage) {
  try { return normalizeAdminLocale(storage().getItem(ADMIN_LOCALE_STORAGE_KEY)); } catch { return "vi"; }
}
